head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF07403.xml";
scwin.isSetPopup = false;
scwin.isMailPopup = true;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/**
 * 콤보박스 값 설정
 */
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "SPECY_VALU_INST_CD",
        cnm: "cmb_SPECY_VALU_INST_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    strCbd = "''^''전체"; //초기값
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_grdSearchCode = function() {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD', 'SPECY_VALU_INST_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    strCbdReason = "' ':"; //초기값

    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") == "SPECY_VALU_INST_CD") {
            strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'SPECY_VALU_INST_CD', 'Data', strCbdReason);
    strCbdReason = "' ':"; //초기값

    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") == "SPECY_VALU_INST_TP_CD") {
            strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
        }
    }
    $c.cm.setColumnProp(grd_Grid, 'SPECY_VALU_INST_TP_CD', 'Data', strCbdReason);
};
scwin.fn_list_sync = function() {
    var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectValuInstPnt&inputMessageId=VALU_INST_PNT_INOUT";
    url += "&SPECY_VALU_INST_CD=" + $c.stf.getObjectValue(cmb_SPECY_VALU_INST_CD); // 평가기관
    url += "&CHRG_NM=" + $c.stf.getObjectValue(txb_CHRG_NM); // 담당자명

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_save = function() {
    TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_CheckForm = function() {
    for (var i = 1, j = dts_List.getTotalRow(); i <= j; i++) {
        var status = dts_List.getRowStatus(i);
        if (status == 1 || status == 3) {
            if (dts_List.getCellData(i, "SPECY_VALU_INST_CD") == "") {
                $c.win.alert(i + "번째행" + " 기관명은 필수값입니다.");
                return false;
            }
            if (dts_List.getCellData(i, "SPECY_VALU_INST_TP_CD") == "") {
                $c.win.alert(i + "번째행" + " 구분값은 필수값입니다.");
                return false;
            }
        }
    }
    return true;
};
scwin.fn_trs = function() {
    if (TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveInstPnt");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};
scwin.fn_chkSelect = async function() {
    var arrPar;
    var selNum = 0;
    var isFirst = true;
    for (var i = 1, j = dts_List.getTotalRow(); i <= j; i++) {
        if (dts_List.getCellData(i, "CHK_YN") == "T") {
            arrPar = new Array();
            arrPar[0] = dts_List.getCellData(i, 'CHRG_NM');
            arrPar[1] = dts_List.getCellData(i, 'CHRG_EMAIL');
            selNum++;
            if (scwin.fn_SetPar != undefined) {
                if (selNum != 1) {
                    isFirst = false;
                }
                scwin.fn_SetPar(arrPar, isFirst);
            }
        }
    }
    await $c.frame.CloseFrame();
};
scwin.btn_Search1_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_Grid, "평가기관담당자", "", 8, 0);
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_searchCode();
    scwin.fn_grdSearchCode();
    scwin.fn_list_sync();
    var parentWin = $c.frame.path("../");
    var parScrenId = parentWin.scwin.vScrenID;
    if (parScrenId == "ULDSTF07041.gfm" || parScrenId == "ULDSTF07404.gfm") {
        scwin.isSetPopup = true;
        scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
        $c.stf.showObj(btn_New, false);
        $c.stf.showObj(btn_Delete, false);
        $c.stf.showObj(btn_Modify, false);
        $c.stf.showObj(btn_Excel, false);
    }
    if (parScrenId != "ULDSTF07404.gfm") {
        $c.cm.setColumnProp(grd_Grid, "CHK_YN", "Show", false);
        $c.stf.showObj(btn_Select, false);
        scwin.isMailPopup = false;
    }
};
scwin.btn_New_onclick = function() {
    dts_List.insertRow();
};
scwin.txb_CHRG_NM_onkeydown = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Delete_onclick = function() {
    $c.cp.removeRow(dts_List, dts_List.getRowPosition());
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_save();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_list_sync();
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (scwin.isSetPopup && !scwin.isMailPopup) {
        var arrPar = new Array();
        if (scwin.fn_SetPar != undefined) {
            arrPar[0] = dts_List.getCellData(dts_List.getRowPosition(), 'CHRG_NM');
            arrPar[1] = dts_List.getCellData(dts_List.getRowPosition(), 'COM_TEL_NO');
            arrPar[2] = dts_List.getCellData(dts_List.getRowPosition(), 'CHRG_EMAIL');
            scwin.fn_SetPar(arrPar);
        }
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Select_onclick = function() {
    scwin.fn_chkSelect();
};
